INSERT INTO `cocktails` (`id`, `name`, `category`, `alcoholic`, `instructions`, `ingredients`, `flavor`) VALUES
(101, 'A1', 'Cocktail', 'Alcoholic', 'Pour all ingredients into a cocktail shaker, mix and serve over ice into a chilled glass.', 'Gin, Grand Marnier, Lemon Juice, Grenadine', 'Fruité, sucré, sucré'),
(102, 'Ace', 'Cocktail', 'Alcoholic', 'Shake all the ingredients in a cocktail shaker and ice then strain in a cold glass.', 'Gin, Grenadine, Heavy cream, Milk, Egg White', 'Fruité, sucré, sucré'),
(103, 'ABC', 'Shot', 'Alcoholic', 'Layered in a shot glass.', 'Amaretto, Baileys irish cream, Cognac', 'Crémeux'),
(104, 'ACID', 'Shot', 'Alcoholic', 'Poor in the 151 first followed by the 101 served with a Coke or Dr Pepper chaser.', '151 proof rum, Wild Turkey', 'Fruité'),
(105, 'Adam', 'Ordinary Drink', 'Alcoholic', 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a cocktail glass.', 'Dark rum, Lemon juice, Grenadine', 'Fruité, sucré, sucré'),
(106, 'AT&T', 'Ordinary Drink', 'Alcoholic', 'Pour Vodka and Gin over ice, add Tonic and Stir', 'Absolut Vodka, Gin, Tonic water', 'Fruité'),
(107, 'A. J.', 'Ordinary Drink', 'Alcoholic', 'Shake ingredients with ice, strain into a cocktail glass, and serve.', 'Applejack, Grapefruit juice', 'Fruité, sucré'),
(108, 'Karsk', 'Ordinary Drink', 'Alcoholic', 'Put a copper coin in a coffe-cup and fill up with coffee until you no longer see the coin, then add alcohol until you see the coin. Norwegian speciality.', 'Coffee, Grain alcohol', 'Fruité'),
(109, 'Melya', 'Coffee / Tea', 'Non alcoholic', 'Brew espresso. In a coffee mug, place 1 teaspoon of unsweetened powdered cocoa, then cover a teaspoon with honey and drizzle it into the cup. Stir while the coffee brews, this is the fun part. The cocoa seems to coat the honey without mixing, so you get a dusty, sticky mass that looks as though it will never mix. Then all at once, presto! It looks like dark chocolate sauce. Pour hot espresso over the honey, stirring to dissolve. Serve with cream.', 'Espresso, Honey, Cocoa powder', 'Fruité, sucré'),
(110, 'Casino', 'Ordinary Drink', 'Alcoholic', 'Pour all ingredients into shaker with ice cubes. Shake well. Strain into chilled cocktail glass. Garnish with a lemon twist and a maraschino cherry. Serve without a straw.', 'Gin, Maraschino liqueur, Lemon juice, Orange bitters, Cherry', 'Fruité, sucré, sucré'),
(111, 'Affair', 'Ordinary Drink', 'Alcoholic', 'Pour schnapps, orange juice, and cranberry juice over ice in a highball glass. Top with club soda and serve.', 'Strawberry schnapps, Orange juice, Cranberry juice, Club soda', 'Fruité, sucré'),
(112, 'Radler', 'Ordinary Drink', 'Alcoholic', 'Pour beer into large mug, slowly add the 7-up (or Sprite).', 'Beer, 7-Up', 'Fruité'),
(113, 'Paloma', 'Cocktail', 'Alcoholic', 'Stir together and serve over ice.', 'Grape Soda, Tequila', 'Fruité'),
(114, 'Boxcar', 'Ordinary Drink', 'Alcoholic', 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a sour glass.', 'Gin, Triple sec, Lemon juice, Grenadine, Egg white', 'Fruité, sucré, sucré'),
(115, 'Mimosa', 'Ordinary Drink', 'Alcoholic', 'Ensure both ingredients are well chilled, then mix into the glass. Serve cold.', 'Champagne, Orange juice', 'Fruité, sucré'),
(116, 'Avalon', 'Ordinary Drink', 'Alcoholic', 'Fill a tall glass with ice. Layer the Finlandia Vodka, lemon and apple juices, Pisang Ambon, and top up with lemonade. Stir slightly and garnish with a spiralled cucumber skin and a red cherry. The cucumber provides zest and looks attractive. This drink, created by Timo Haimi, took first prize in the 1991 Finlandia Vodka Long Drink Competition.', 'Vodka, Pisang Ambon, Apple juice, Lemon juice, Lemonade', 'Fruité, sucré'),
(117, 'Apello', 'Other / Unknown', 'Non alcoholic', 'Stirr. Grnish with maraschino cherry.', 'Orange juice, Grapefruit juice, Apple juice, Maraschino cherry', 'Fruité, sucré'),
(118, 'Orgasm', 'Ordinary Drink', 'Alcoholic', 'Shake all ingredients with ice, strain into a chilled cocktail glass, and serve.', 'Creme de Cacao, Amaretto, Triple sec, Vodka, Light cream', 'Crémeux'),
(119, 'Ipamena', 'Ordinary Drink', 'Non alcoholic', 'Cut half a lime into pieces, place in a shaker, add the sugar and crush. Measure the passion fruit juice, add it to the shaker and fill up with ice cubes. Close the shaker and shake vigorously. Pour the liquid into a glass, top up with ginger ale, stir with a teaspoon and then garnish the rim of the glass with a slice of lime', 'Lime, Brown sugar, Passion fruit juice, Ginger ale, Ice', 'Acide, épicé, sucré, épicé'),
(120, 'Zambeer', 'Soft Drink', 'Alcoholic', 'Mix sambuca with rootbeer and stir. Add ice', 'Sambuca, Root beer, Ice', 'Fruité'),
(121, 'Bramble', 'Ordinary Drink', 'Alcoholic', 'Fill glass with crushed ice. Build gin, lemon juice and simple syrup over. Stir, and then pour blackberry liqueur over in a circular fashion to create marbling effect. Garnish with two blackberries and lemon slice.', 'Gin, lemon juice, Sugar syrup, Creme de Mure', 'Crémeux, sucré'),
(122, 'Sazerac', 'Ordinary Drink', 'Alcoholic', 'Rinse a chilled old-fashioned glass with the absinthe, add crushed ice, and set it aside. Stir the remaining ingredients over ice and set it aside. Discard the ice and any excess absinthe from the prepared glass, and strain the drink into the glass. Add the lemon peel for garnish.', 'Ricard, Sugar, Peychaud bitters, Water, Bourbon, Lemon peel', 'Fumé, sucré'),
(123, 'Almeria', 'Ordinary Drink', 'Alcoholic', 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a cocktail glass.', 'Dark rum, Kahlua, Egg white', 'Fruité'),
(124, 'Addison', 'Cocktail', 'Alcoholic', 'Shake together all the ingredients and strain into a cold glass.', 'Gin, Vermouth', 'Amer'),
(125, 'Vampiro', 'Ordinary Drink', 'Alcoholic', 'Vampiros may be made in a tall glass or an old fashioned glass. Bartenders may first \"rim\" the glass with Kosher Salt, which is done by placing a layer of Kosher Salt on a chopping board, moistening the glass\' rim with lime juice or water, and then placing the upside down glass rim onto the Kosher Salt, so that the salt sticks to the moistened rim. The second step is to fill half the glass with ice and add one or two shooter glasses full of high quality Tequila. The next stage is to add the flavouring elements. This is done by squeezing a fresh lime into the glass, adding a few grains of salt, adding citrus-flavoured soda pop, until the glass is 4/5 full, and then adding spicy Viuda de Sanchez (or orange juice, lime juice and pico de gallo). The final step is to stir the ingredients so that the flavours are properly blended.', 'Tequila, Tomato Juice, Orange Juice, Lime Juice, Sugar Syrup, Salt', 'Acide, sucré, salé'),
(126, 'ABC', 'Shot', 'Alcoholic', 'Layered in a shot glass.', 'Amaretto, Baileys irish cream, Cognac', 'Crémeux'),
(127, 'B-53', 'Shot', 'Alcoholic', 'Layer the Kahlua, Sambucca and Grand Marnier into a shot glas in that order. Better than B-52', 'Kahlua, Sambuca, Grand Marnier', 'Fruité'),
(128, 'B-52', 'Shot', 'Alcoholic', 'Layer ingredients into a shot glass. Serve with a stirrer.', 'Baileys irish cream, Grand Marnier, Kahlua', 'Crémeux'),
(129, 'Derby', 'Ordinary Drink', 'Alcoholic', 'Pour all ingredients into a mixing glass with ice. Stir. Strain into a cocktail glass. Garnish with a sprig of fresh mint in the drink.', 'gin, Peach Bitters, Mint', 'Fruité'),
(130, 'Bijou', 'Cocktail', 'Alcoholic', 'Stir in mixing glass with ice and strain\r\n', 'Orange Bitters, Green Chartreuse, Gin, Sweet Vermouth', 'Amer, sucré'),
(131, 'Zombie', 'Cocktail', 'Alcoholic', 'Blend at high speed for no more than 5 seconds.\n\nPour into a glass, add ice cubes to fill, then add the garnish.\n\n*Donn’s mix: Bring 3 crushed cinnamon sticks, 1 cup of sugar and 1 cup of water to a boil, stirring until the sugar is dissolved.\n\nSimmer for 2 minutes, then remove from the heat and let sit for at least 2 hours before straining into a clean glass bottle.\n\nThen add 1 part of the syrup and 2 parts of fresh grapefruit juice together.', 'Rum, Gold rum, 151 proof rum, Pernod, Grenadine, Lime Juice, Angostura Bitters', 'Acide, sucré, sucré'),
(132, 'Boxcar', 'Ordinary Drink', 'Alcoholic', 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a sour glass.', 'Gin, Triple sec, Lemon juice, Grenadine, Egg white', 'Fruité, sucré, sucré'),
(133, 'Abilene', 'Ordinary Drink', 'Alcoholic', 'Pour all of the ingredients into a highball glass almost filled with ice cubes. Stir well.', 'Dark rum, Peach nectar, Orange juice', 'Fruité, sucré'),
(134, 'Zambeer', 'Soft Drink', 'Alcoholic', 'Mix sambuca with rootbeer and stir. Add ice', 'Sambuca, Root beer, Ice', 'Fruité'),
(135, 'Bramble', 'Ordinary Drink', 'Alcoholic', 'Fill glass with crushed ice. Build gin, lemon juice and simple syrup over. Stir, and then pour blackberry liqueur over in a circular fashion to create marbling effect. Garnish with two blackberries and lemon slice.', 'Gin, lemon juice, Sugar syrup, Creme de Mure', 'Crémeux, sucré'),
(136, 'Big Red', 'Shot', 'Alcoholic', 'Pour ingredients into 1 ounce shot glass', 'Irish cream, Goldschlager', 'Fruité'),
(137, 'Bellini', 'Ordinary Drink', 'Alcoholic', 'Pour peach purée into chilled flute, add sparkling wine. Stir gently.', 'Champagne, Peach schnapps', 'Fruité'),
(138, 'Brooklyn', 'Cocktail', 'Alcoholic', 'Combine ingredients with ice and stir until well-chilled. Strain into a chilled cocktail glass.', 'Rye Whiskey, Dry Vermouth, Maraschino Liqueur, Angostura Bitters, Maraschino Cherry', 'Amer, sucré, sucré'),
(139, 'Balmoral', 'Ordinary Drink', 'Alcoholic', 'In a mixing glass half-filled with ice cubes, combine all of the ingredients. Stir well. Strain into a cocktail glass.', 'Scotch, Sweet Vermouth, Dry Vermouth, Bitters', 'Amer, sucré'),
(140, 'Snowball', 'Ordinary Drink', 'Alcoholic', 'Place one ice cube in the glass and add 1 1/2 oz of Advocaat. Fill up the glass with lemonade and decorate with a slice of lemon. Serve at once.', 'Advocaat, Lemonade, Lemon, Ice', 'Fruité'),
(141, 'Danbooka', 'Coffee / Tea', 'Alcoholic', 'pour it in and mix it.', 'Coffee, Everclear', 'Fruité'),
(142, 'Bluebird', 'Ordinary Drink', 'Alcoholic', 'In a mixing glass half-filled with crushed ice, combine the gin, triple sec, Curacao, and bitters. Stir well. Strain into a cocktail glass and garnish with the lemon twist and the cherry.', 'Gin, Triple sec, Blue Curacao, Bitters, Maraschino cherry, Lemon peel', 'Fruité'),
(143, '501 Blue', 'Ordinary Drink', 'Alcoholic', 'Mix equal amounts into a glass with ice.', 'Blue Curacao, Blueberry schnapps, Vodka, Sour mix, 7-Up', 'Fruité'),
(144, 'Pegu Club', 'Cocktail', 'Alcoholic', 'Shake, strain, up, cocktail glass', 'Gin, Orange Curacao, Lime Juice, Angostura Bitters, Orange Bitters', 'Acide, sucré'),
(145, 'Old Cuban', 'Cocktail', 'Alcoholic', 'Shake a handful of mint, 2oz white rum, 1oz of sugar syrup, 1oz lime juice and 2 dashes angostura bitters with ice. Double strain into a glass and top with 2oz of prosecco.', 'White Rum, Sugar Syrup, Lime Juice, Angostura Bitters, Prosecco', 'Acide, sucré'),
(146, 'Boomerang', 'Ordinary Drink', 'Alcoholic', 'In a mixing glass half-filled with ice cubes, combine the gin, vermouth, bitters, and maraschino liqueur. Stir well. Strain into a cocktail glass and garnish with the cherry.', 'Gin, Dry Vermouth, Bitters, Maraschino liqueur, Maraschino cherry', 'Amer, sucré, sucré'),
(147, 'Barracuda', 'Ordinary Drink', 'Alcoholic', 'Shake pour ingredients with ice. Strain into glass, top with Sparkling wine.', 'Rum, Galliano, Pineapple Juice, Lime Juice, Prosecco', 'Acide, sucré'),
(148, 'Bora Bora', 'Cocktail', 'Non alcoholic', 'Prepare in a blender or shaker, serve in a highball glass on the rocks. Garnish with 1 slice of pineapple and one cherry.', 'Pineapple juice, Passion fruit juice, Lemon juice, Grenadine', 'Fruité, sucré, sucré'),
(149, 'Lunch Box', 'Beer', 'Alcoholic', 'Fill a pint glass almost full with beer. Then fill the rest with orange juice (careful not to fill it to the top). Then take the shot of Amaretto and drop it in.', 'Beer, Amaretto, Orange juice', 'Fruité, sucré'),
(150, 'Jitterbug', 'Cocktail', 'Alcoholic', 'Wet glass, dip rim in sugar. Then add Ice. Then add everything else. It\'s that simple!', 'Gin, Vodka, Grenadine, Lime juice, Sugar, Sugar syrup, Soda water', 'Acide, sucré, sucré'),
