(579, 'Victor', 'Ordinary Drink', 'Alcoholic', 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Gin, Sweet Vermouth, Brandy', 'Amer, sucré'),
(580, 'Gimlet', 'Cocktail', 'Alcoholic', 'Add all the ingredients to a shaker and fill with ice.\r\n\r\nShake, and strain into a chilled cocktail glass or an Old Fashioned glass filled with fresh ice.\r\n\r\nGarnish with a lime wheel.', 'Gin, Lime Juice, Sugar Syrup, Lime', 'Acide, sucré'),
